/*
 Problem: 3871. Count Commas in Range II
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9.1 MB (14.30%)
 Tags: Math
*/
class Solution {
public:
    long long countCommas(long long n) {
        long long ans = 0;
        for (long long p = 1000; p <= n; p *= 1000)
            ans += n - p + 1;

        return ans;
    }
};
